// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz the caller address (from) and a non-empty array length and a value v
    function testFuzz_property(address from, uint8 tosLen, uint256 v) public {
        // keep tosLen small but allow zero to be excluded by assumption
        tosLen = uint8(bound(tosLen, 0, 5));
        vm.assume(tosLen > 0);

        // deploy a RecordingReverter that implements transferFrom(address,address,uint256)
        // It will revert if the selector does not match a defined function (i.e., if calldata targets a different selector),
        // and will record calls when selector matches. We also provide a failing mode that reverts when called.
        RecorderReverter rec = new RecorderReverter();

        // build tos array of addresses all pointing to our recorder (so loop runs tosLen times)
        address[] memory tos = new address[](tosLen);
        for (uint i = 0; i < tosLen; i++) tos[i] = address(rec);

        // Call transfer and observe whether it reverts. The correct contract uses selector transferFrom(...)
        // which matches the recorder's explicit function and will succeed; the mutant using a different selector
        // will cause the low-level call to hit fallback and the recorder will revert, making c.transfer revert.
        bool ok;
        try c.transfer(from, address(rec), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: for any admissible inputs (tosLen>0, any from, any v), the reference C never reverts
        // (ok == true). The mutant that changed the selector will make some inputs (here any with tosLen>0)
        // produce a revert (ok == false). Assert that the call did NOT revert.
        assertTrue(ok);
    }
}

// This helper declares the exact function signature that the reference contract expects:
// function transferFrom(address from, address to, uint256 v) external returns (bool);
// When called with the correct selector, it records the last call and returns true.
// For any other selector (malformed selector from mutant), the fallback reverts to cause the call to fail.
contract RecorderReverter {
    address public lastFrom;
    address public lastTo;
    uint256 public lastV;
    uint256 public calls;

    // matching selector
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        lastFrom = from;
        lastTo = to;
        lastV = v;
        calls += 1;
        return true;
    }

    // any other call (wrong selector) will hit fallback and revert, exposing the mutant's incorrect selector
    fallback() external payable {
        revert("bad selector");
    }
}
